  "client/core/Kniu-Ui/Kniu-AuthLayoutComponent/Kniu-AuthLayoutComponent.css": ":host {\n  display: block;\n  width: 100%;\n  min-height: 100vh;\n}\n\n.kniu_sys_auth_layout {\n  position: fixed;\n  inset: 0;\n  display: flex;\n  align-items: flex-start;\n  justify-content: center;\n  overflow: auto;\n  padding: 24px 0;\n  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\n}\n\n.kniu_sys_auth_layout::before,\n.kniu_sys_auth_layout::after {\n  position: fixed;\n  border-radius: 50%;\n  pointer-events: none;\n  content: \"\";\n}\n\n.kniu_sys_auth_layout::before {\n  top: -18%;\n  right: -8%;\n  width: 520px;\n  height: 520px;\n  background: radial-gradient(circle, rgba(255, 255, 255, .18), transparent 70%);\n}\n\n.kniu_sys_auth_layout::after {\n  bottom: -16%;\n  left: -10%;\n  width: 460px;\n  height: 460px;\n  background: radial-gradient(circle, rgba(255, 255, 255, .12), transparent 70%);\n}\n\n.kniu_sys_auth_card {\n  z-index: 1;\n  width: 400px;\n  max-width: 92vw;\n  margin: auto;\n  overflow: hidden;\n  border-radius: 12px;\n  background: #fff;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, .25);\n}\n\n.kniu_sys_auth_header { padding: 32px 24px 0; text-align: center; }\n.kniu_sys_auth_brand { display: flex; align-items: center; justify-content: center; gap: 6px; margin-bottom: 8px; }\n.kniu_sys_auth_mark { display: flex; align-items: center; justify-content: center; width: 40px; height: 40px; border-radius: 8px; background: #23262e; color: #fff; font-size: 20px; font-weight: 700; }\n.kniu_sys_auth_name { color: #23262e; font-size: 22px; font-weight: 700; }\n.kniu_sys_auth_name strong { color: #667eea; }\n.kniu_sys_auth_subtitle { margin: 6px 0 0; color: #999; font-size: 13px; }\n.kniu_sys_auth_body { padding: 20px 24px 28px; }\n.kniu_sys_auth_footer { padding: 0 40px 26px; color: #bbb; font-size: 12px; text-align: center; }\n\n@media (min-width: 481px) {\n  .kniu_sys_auth_header, .kniu_sys_auth_body { padding-right: 40px; padding-left: 40px; }\n}\n",
  "client/core/Kniu-Ui/Kniu-BacktopComponent/Kniu-BacktopComponent.css": "@charset \"UTF-8\";\r\n\r\n:host {\r\n  z-index: 40;\r\n  position: fixed;\r\n  right: calc(16 / var(--kniu_vw));\r\n  bottom: calc(16 / var(--kniu_vw));\r\n  display: none;\r\n}\r\n\r\n:host([visible]) {\r\n  display: block;\r\n}\r\n\r\n.kniu_sys_backtop_btn {\r\n  display: grid;\r\n  place-items: center;\r\n  border: 1px solid var(--kniu-border-color-light, #e4e7ed);\r\n  border-radius: 50%;\r\n  -webkit-border-radius: 50%;\r\n  -moz-border-radius: 50%;\r\n  -ms-border-radius: 50%;\r\n  -o-border-radius: 50%;\r\n  width: max(30px, calc(40 / var(--kniu_vw)));\r\n  height: max(30px, calc(40 / var(--kniu_vw)));\r\n  background-color: var(--kniu-surface-color, #fff);\r\n  color: #374151;\r\n  cursor: pointer;\r\n  box-shadow: 0 8px 24px rgba(15, 23, 42, .14);\r\n  -webkit-box-shadow: 0 8px 24px rgba(15, 23, 42, .14);\r\n  -moz-box-shadow: 0 8px 24px rgba(15, 23, 42, .14);\r\n  -ms-box-shadow: 0 8px 24px rgba(15, 23, 42, .14);\r\n  -o-box-shadow: 0 8px 24px rgba(15, 23, 42, .14);\r\n  transition: transform .2s, box-shadow .2s;\r\n  -webkit-transition: transform .2s, box-shadow .2s;\r\n  -moz-transition: transform .2s, box-shadow .2s;\r\n  -ms-transition: transform .2s, box-shadow .2s;\r\n  -o-transition: transform .2s, box-shadow .2s;\r\n}\r\n\r\n.kniu_sys_backtop_icon {\r\n  display: block;\r\n  width: max(13.5px, calc(18 / var(--kniu_vw)));\r\n  height: max(13.5px, calc(18 / var(--kniu_vw)));\r\n}\r\n\r\n.kniu_sys_backtop_btn:hover {\r\n  transform: translateY(-2px);\r\n  -webkit-transform: translateY(-2px);\r\n  -moz-transform: translateY(-2px);\r\n  -ms-transform: translateY(-2px);\r\n  -o-transform: translateY(-2px);\r\n  box-shadow: 0 12px 28px rgba(15, 23, 42, .18);\r\n  -webkit-box-shadow: 0 12px 28px rgba(15, 23, 42, .18);\r\n  -moz-box-shadow: 0 12px 28px rgba(15, 23, 42, .18);\r\n  -ms-box-shadow: 0 12px 28px rgba(15, 23, 42, .18);\r\n  -o-box-shadow: 0 12px 28px rgba(15, 23, 42, .18);\r\n}\r\n\r\n@media(min-width:calc(1280px - 60px)) {\r\n  /* 原 right / bottom 带 !important。竞争对象只有本文件顶部的\r\n   * `:host { right: calc(16 / var(--kniu_vw)) }`（同为 0,1,0），\r\n   * 媒体查询内的同名规则按源码顺序在其后，无需提升优先级即胜出；\r\n   * 运行时 _syncPosition() 只写 --right / --bottom 两个自定义属性，\r\n   * 不写宿主行内 right/bottom，故 !important 冗余。 */\r\n  :host {\r\n    right: min(var(--right, 40px), calc(100vw - 56px));\r\n    bottom: min(var(--bottom, 40px), calc(100vh - 56px));\r\n  }\r\n\r\n  .kniu_sys_backtop_btn {\r\n    width: max(30px, calc(44 / var(--kniu_vw)));\r\n    height: max(30px, calc(44 / var(--kniu_vw)));\r\n  }\r\n\r\n  .kniu_sys_backtop_icon {\r\n    width: max(13.5px, calc(20 / var(--kniu_vw)));\r\n    height: max(13.5px, calc(20 / var(--kniu_vw)));\r\n  }\r\n}\r\n\r\n@media(prefers-reduced-motion:reduce) {\r\n  .kniu_sys_backtop_btn {\r\n    transition: none;\r\n    -webkit-transition: none;\r\n    -moz-transition: none;\r\n    -ms-transition: none;\r\n    -o-transition: none;\r\n  }\r\n}",
