  "client/core/Kniu-Ui/Kniu-BtnComponent/Kniu-BtnComponent.Overrides.css": "@charset \"UTF-8\";\n\n.kniu_sys_button_icon {\n  display: inline-flex;\n  display: -webkit-inline-flex;\n  justify-content: center;\n  -webkit-justify-content: center;\n  -moz-justify-content: center;\n  -ms-justify-content: center;\n  -o-justify-content: center;\n  align-items: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  -ms-align-items: center;\n  -o-align-items: center;\n}\n\n.kniu_sys_button_icon Kniu-Icon {\n  display: block;\n  width: 1em;\n  height: 1em;\n  overflow: visible;\n}\n\n:host([block]) {\n  height: 100%;\n}\n\n:host([block]) .kniu_sys_button {\n  width: 100%;\n  height: 100%;\n}\n\nslot::slotted(Kniu-Icon) {\n  font-size: var(--kniu-button-icon-size, 1em);\n}\n\n:host([append-borderless]) .kniu_sys_button {\n  border: none;\n  border-radius: 0;\n  -webkit-border-radius: 0;\n  -moz-border-radius: 0;\n  -ms-border-radius: 0;\n  -o-border-radius: 0;\n}",
  "client/core/Kniu-Ui/Kniu-BtnGroupComponent/Kniu-BtnGroupComponent.css": "@charset \"UTF-8\";\r\n\r\n:host {\r\n  display: inline-flex;\r\n  display: -webkit-inline-flex;\r\n  align-items: center;\r\n  -webkit-align-items: center;\r\n  -moz-align-items: center;\r\n  -ms-align-items: center;\r\n  -o-align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n:host([block]) {\r\n  display: flex;\r\n  display: -webkit-flex;\r\n  gap: 10px;\r\n  /* 本节 margin-top 必须带 !important（真机实测回归，勿删）。\r\n   *\r\n   * 竞争者是 Kniu-Base.css 注入同一 shadow 的全局 reset：\r\n   *   *, ::before, ::after { margin: 0; }\r\n   * 它经 adoptSharedStyle() 成为该 shadow 的第 1 张 adoptedStyleSheets，\r\n   * 本文件是第 5 张。\r\n   *\r\n   * 按理论特异性 :host([block]) = (0,1,1) 应高于 `*` = (0,0,0)，两份源码注释\r\n   * 曾据此判定 !important 冗余。但真机实测（Chrome 156，1440x900）证明：\r\n   * ① 移除后 /login 页真实 <kniu-btn-group block> 的 marginTop = 0px；\r\n   * ② 即使把 adoptedStyleSheets 换成「只留一张 :host([block]) 表、内仅一条\r\n   *    非 important 的较大 margin-top」，marginTop 仍为 0，而同一张表里的\r\n   *    display 声明正常生效；\r\n   * ③ 加回 !important 后 margin-top 立刻恢复。\r\n   * 即 :host 作用于宿主的盒模型外扩属性会被 shadow 内 `*` reset 压下，\r\n   * 且该行为与特异性无关。恢复 !important 是当前唯一稳定解法。\r\n   *\r\n   * 属规则 2.7.2.1 的「压制跨表 reset」豁免情形：不是压制业务规则，\r\n   * 而是让 :host 声明能压过全局 reset。 */\r\n  margin-top: 20px !important;\r\n  width: 100%;\r\n}\r\n\r\n:host([block]) ::slotted(*) {\r\n  flex: 1 1 0;\r\n  -webkit-flex: 1 1 0;\r\n  -moz-flex: 1 1 0;\r\n  -ms-flex: 1 1 0;\r\n  -o-flex: 1 1 0;\r\n  min-width: 0;\r\n}",
