  "client/core/Kniu-Ui/Kniu-Other/Kniu-Base.css": "@charset \"UTF-8\";\n\n:root,\n:host {\n  --kniu_vw: 640 * 100vw;\n  --kniu_vh: 360 * 100vh;\n}\n\n@media (min-width: calc(1024px - 60px)) {\n\n  :root,\n  :host {\n    --kniu_vw: 1920 * 100vw;\n    --kniu_vh: 1080 * 100vh;\n  }\n}\n\n*,\n*:before,\n*:after {\n  border: none;\n  outline: none;\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  -webkit-box-sizing: border-box;\n  -moz-box-sizing: border-box;\n  -ms-box-sizing: border-box;\n  -o-box-sizing: border-box;\n  user-select: none;\n  -webkit-user-select: none;\n  -moz-user-select: none;\n  -ms-user-select: none;\n  -o-user-select: none;\n  word-break: break-word;\n}\n\n/* 规则 2.7.2 显式豁免点。\n *\n * 本文件是注入每个 shadow host 的全局 reset 基类，`* { user-select: none }`\n * 之上的“禁选”是刻意设计，必须有一条反向规则把可编辑元素的选取能力还回来。\n * 输入类元素由浏览器内置，业务代码无法在其上预置语义类名，因此这里只能按\n * 标签选择器书写；换成类选择器会漏掉所有未加类的 input/textarea，\n * 造成正文不可选中（比规则违规更严重）。新增同类反向规则时沿用此处豁免。\n */\ninput,\ntextarea,\n[contenteditable] {\n  user-select: text;\n  -webkit-user-select: text;\n  -moz-user-select: text;\n  -ms-user-select: text;\n  -o-user-select: text;\n}\n\n.kniu_float_right {\n  float: right;\n}\n\n.kniu_clear_float::after {\n  content: \"\";\n  display: block;\n  clear: both;\n}\n\n.kniu_flex_betweencenter {\n  display: flex;\n  display: -webkit-flex;\n  justify-content: space-between;\n  -webkit-justify-content: space-between;\n  -moz-justify-content: space-between;\n  -ms-justify-content: space-between;\n  -o-justify-content: space-between;\n  align-items: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  -ms-align-items: center;\n  -o-align-items: center;\n}\n\n.kniu_flex_centercenter {\n  display: flex;\n  display: -webkit-flex;\n  justify-content: center;\n  -webkit-justify-content: center;\n  -moz-justify-content: center;\n  -ms-justify-content: center;\n  -o-justify-content: center;\n  align-items: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  -ms-align-items: center;\n  -o-align-items: center;\n}\n\n.kniu_flex_rightcenter {\n  display: flex;\n  display: -webkit-flex;\n  justify-content: flex-end;\n  -webkit-justify-content: flex-end;\n  -moz-justify-content: flex-end;\n  -ms-justify-content: flex-end;\n  -o-justify-content: flex-end;\n  align-items: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  -ms-align-items: center;\n  -o-align-items: center;\n}\n\n.kniu_flex_leftcenter {\n  display: flex;\n  display: -webkit-flex;\n  justify-content: flex-start;\n  -webkit-justify-content: flex-start;\n  -moz-justify-content: flex-start;\n  -ms-justify-content: flex-start;\n  -o-justify-content: flex-start;\n  align-items: center;\n  -webkit-align-items: center;\n  -moz-align-items: center;\n  -ms-align-items: center;\n  -o-align-items: center;\n}\n\n.kniu_gap_10 {\n  gap: calc(10 / var(--kniu_vw));\n}\n\n.kniu_mb_10 {\n  margin-bottom: calc(10 / var(--kniu_vw));\n}\n\n.kniu_mb_20 {\n  margin-bottom: calc(20 / var(--kniu_vw));\n}\n\n.kniu_mb_30 {\n  margin-bottom: calc(30 / var(--kniu_vw));\n}",
